// Place this immediately after an n8n Webhook node protected by Header Auth.
// Configure Header Auth to require X-Zibashe-Webhook-Token using an encrypted n8n credential.
const webhook = $input.first().json;
const headers = Object.fromEntries(
  Object.entries(webhook.headers ?? {}).map(([key, value]) => [key.toLowerCase(), value]));
const body = typeof webhook.body === 'string' ? JSON.parse(webhook.body) : webhook.body;

function reject(message) {
  throw new Error(`Rejected Zibashe event: ${message}`);
}

const eventIdHeader = String(headers['x-zibashe-event-id'] ?? '').toLowerCase();
const timestampHeader = String(headers['x-zibashe-timestamp'] ?? '');
const signatureHeader = String(headers['x-zibashe-signature'] ?? '');
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!body || typeof body !== 'object' || Array.isArray(body)) reject('body is not a JSON object');
if (!uuidPattern.test(eventIdHeader)) reject('event ID header is invalid');
if (String(body.eventId ?? '').toLowerCase() !== eventIdHeader) reject('event ID header and body differ');
if (!/^sha256=[0-9a-f]{64}$/i.test(signatureHeader)) reject('HMAC signature header format is invalid');

const timestamp = Number(timestampHeader);
if (!Number.isSafeInteger(timestamp) || timestamp <= 0) reject('timestamp is invalid');
const ageSeconds = Math.abs(Math.floor(Date.now() / 1000) - timestamp);
if (ageSeconds > 300) reject('timestamp is outside the five-minute window');

const allowedTypes = new Set(['InvoiceIssued', 'OrderDecanted', 'OrderShipped']);
if (!allowedTypes.has(body.eventType)) reject('event type is not supported');
if (!uuidPattern.test(String(body.customerId ?? ''))) reject('customer ID is invalid');
if (!uuidPattern.test(String(body.orderId ?? ''))) reject('order ID is invalid');
if (!body.data || typeof body.data !== 'object' || Array.isArray(body.data)) reject('data is invalid');

const delivery = body.data.Delivery;
if (delivery !== null) {
  if (!delivery || delivery.Channel !== 'TelegramGroup') reject('delivery channel is invalid');
  if (!/^-[1-9][0-9]*$/.test(String(delivery.ChatId ?? ''))) reject('delivery ChatId is invalid');
  if (!String(delivery.Title ?? '').trim()) reject('delivery title is missing');
}

return [{
  json: {
    ...body,
    deliveryReady: delivery !== null,
    receivedAt: new Date().toISOString()
  }
}];

// Paste this file into an n8n Code node configured to run once for all items.
const event = $input.first().json;

function escapeHtml(value) {
  return String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#39;');
}
function number(value) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) throw new Error('Invoice contains an invalid numeric value.');
  return new Intl.NumberFormat('fa-IR', { maximumFractionDigits: 0 }).format(parsed);
}
function money(value) { return `${number(value)} تومان`; }
function persianDate(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) throw new Error('Invoice contains an invalid issue date.');
  return new Intl.DateTimeFormat('fa-IR-u-ca-persian', {
    timeZone: 'Asia/Tehran', year: 'numeric', month: '2-digit', day: '2-digit'
  }).format(date);
}
function formatCard(value) {
  const digits = String(value ?? '').replace(/\D/g, '');
  return digits.length === 16 ? digits.match(/.{1,4}/g).join(' - ') : String(value ?? '');
}

if (event.eventType !== 'InvoiceIssued' || !event.data) throw new Error('Expected an InvoiceIssued event.');
const customerChatId = String(event.data.Delivery?.ChatId ?? '').trim();
const manualReviewChatId = typeof $env === 'undefined'
  ? ''
  : String($env.N8N_INVOICE_FAILURE_CHAT_ID ?? '').trim();
const isManualReview = !customerChatId;
const invoiceDeliveryChatId = customerChatId || manualReviewChatId;
if (!/^-\d+$/.test(invoiceDeliveryChatId)) {
  throw new Error('Invoice has no customer group and N8N_INVOICE_FAILURE_CHAT_ID is not configured.');
}
const invoice = event.data;
const customer = invoice.Customer ?? {};
const items = Array.isArray(invoice.Items) ? invoice.Items : [];
const paymentAccounts = Array.isArray(invoice.PaymentAccounts) ? invoice.PaymentAccounts.slice(0, 4) : [];
const username = String(customer.Username ?? '').trim().replace(/^@/, '');
const customerName = username ? `@${username}` : (customer.FullName ?? 'مشتری زیباشی');
const invoiceFileBase = (username || String(invoice.InvoiceNumber ?? 'invoice'))
  .replace(/[\\/:*?"<>|\u0000-\u001f]/g, '_')
  .replace(/[. ]+$/g, '')
  .slice(0, 80) || 'invoice';
if (items.length === 0) throw new Error('Invoice has no items.');

const renderRows = (pageItems) => pageItems.map((item) => {
  const englishName = item.PerfumeEnglishName ?? item.PerfumeName ?? 'آیتم دستی';
  const persianName = item.PerfumePersianName ?? item.PerfumeName ?? 'آیتم دستی';
  const englishTitle = [item.PerfumeBrand, englishName].filter(Boolean).join(' ');
  return `<div class="invoice-row"><span>${number(item.RowNumber)}</span>
    <span class="item-name"><strong>${escapeHtml(persianName)}</strong><small dir="ltr">${escapeHtml(englishTitle)}</small></span>
    <span>${number(item.RequestedVolumeMl)}</span><span>${number(item.Quantity ?? 1)}</span>
    <span>${number(item.PerfumePricePerMl ?? 0)}</span><span>${number(item.BottlePrice ?? 0)}</span>
    <span>${number(item.LineTotal)}</span></div>`;
}).join('');

const captionLines = [
  `🧾 فاکتور عطر ${customerName}`,
  `تاریخ: ${persianDate(invoice.IssuedAt)}`,
  `شماره فاکتور: ${invoice.InvoiceNumber}`,
  ''
];
if (isManualReview) {
  captionLines.unshift(
    '⚠️ بررسی دستی — گروه گیرنده به سامانه متصل نیست',
    `مشتری: ${customerName}`,
    `فرمان اتصال پس از ساخت/ورود ربات به گروه مشتری: /connect ${invoice.InvoiceNumber}`,
    ''
  );
}
items.forEach((item) => {
  const name = item.PerfumePersianName ?? item.PerfumeEnglishName ?? item.PerfumeName ?? 'آیتم دستی';
  captionLines.push(`🧴 ${name}`);
  captionLines.push(`مقدار: ${number(item.RequestedVolumeMl)} میل`);
  captionLines.push(`مبلغ عطر و شیشه: ${money(item.LineTotal)}`);
  captionLines.push('');
});
captionLines.push(`💰 مبلغ قابل پرداخت: ${money(invoice.TotalAmount)}`);
if (paymentAccounts.length > 0) {
  captionLines.push('', 'شماره کارت جهت واریز:');
  paymentAccounts.forEach((account) => {
    captionLines.push(formatCard(account.CardNumber));
    captionLines.push(`${account.AccountHolder} - بانک ${account.BankName}`);
  });
}
captionLines.push('', 'با تشکر از خرید شما', 'مهلت پرداخت فاکتور: ۲۴ ساعت');
const telegramCaption = captionLines.join('\n').slice(0, 1024);
const invoiceId = String(invoice.InvoiceId ?? '').replaceAll('-', '');
const firstPaymentAccount = paymentAccounts[0] ?? {};
const secondPaymentAccount = paymentAccounts[1] ?? {};
const backgroundImage = 'data:image/jpeg;base64,';
const pages = Array.from(
  { length: Math.ceil(items.length / 8) },
  (_, index) => items.slice(index * 8, index * 8 + 8));
const pagesHtml = pages.map((pageItems, pageIndex) => {
  const isLastPage = pageIndex === pages.length - 1;
  return `<main class="page"><img class="background" src="${backgroundImage}" alt="">
    <div class="field date">${escapeHtml(persianDate(invoice.IssuedAt))}</div>
    <div class="field customer"${username ? ' dir="ltr"' : ''}>${escapeHtml(customerName)}</div>
    <div class="field invoice-number">${escapeHtml(invoice.InvoiceNumber)}</div>
    <div class="field mobile">${escapeHtml(customer.Mobile ?? '-')}</div>
    <div class="table-head"><span>ردیف</span><span>نام عطر</span><span>مقدار (میل)</span><span>تعداد</span><span>قیمت واحد</span><span>قیمت شیشه</span><span>قیمت کل</span></div>
    <section class="rows">${renderRows(pageItems)}</section>
    ${isLastPage ? `<div class="total subtotal">${money(invoice.TotalAmount)}</div>
    <div class="shipping-mask"></div>
    <div class="total final">${money(invoice.TotalAmount)}</div>` : '<div class="shipping-mask"></div>'}
    ${pages.length > 1 ? `<div class="page-counter">صفحه ${number(pageIndex + 1)} از ${number(pages.length)}</div>` : ''}
  </main>`;
}).join('');

const invoiceHtml = `<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8">
<title>فاکتور ${escapeHtml(invoice.InvoiceNumber)}</title><style>
@page{size:A4;margin:0}*{box-sizing:border-box}html,body{margin:0;width:210mm;background:#faefea}body{font-family:"Noto Sans Arabic","Vazirmatn",Tahoma,sans-serif;color:#55151b}.page{position:relative;width:210mm;height:297mm;overflow:hidden;break-after:page;page-break-after:always}.page:last-child{break-after:auto;page-break-after:auto}.background{position:absolute;inset:0;width:100%;height:100%;object-fit:fill;z-index:0}.field{position:absolute;z-index:2;text-align:right;font-weight:700;font-size:11px;line-height:1.25;color:#59131a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.date{top:19.8%;right:24.8%;width:22%}.customer{top:23.5%;right:24.8%;width:22%}.invoice-number{top:27.1%;right:24.8%;width:22%;direction:ltr;text-align:right}.mobile{top:30.7%;right:24.8%;width:22%;direction:ltr;text-align:right}.table-head{position:absolute;z-index:3;top:36%;right:8%;width:84%;height:3.8%;display:grid;grid-template-columns:10% 22% 14% 11% 15% 14% 14%;direction:rtl;align-items:center;text-align:center;background:rgba(239,203,208,.98);border-radius:12px 12px 0 0;color:#531719;font-weight:800;font-size:9.5px}.table-head span{height:100%;display:flex;align-items:center;justify-content:center;padding:0 2px;border-left:1px solid rgba(125,66,70,.2)}.table-head span:last-child{border-left:0}.rows{position:absolute;z-index:2;top:39.7%;right:8%;width:84%;height:29.3%;display:grid;grid-template-rows:repeat(8,1fr);align-content:start;overflow:hidden;background:rgba(250,239,234,.9);border:1px solid rgba(125,66,70,.13);border-top:0;border-radius:0 0 12px 12px}.invoice-row{display:grid;grid-template-columns:10% 22% 14% 11% 15% 14% 14%;direction:rtl;align-items:stretch;text-align:center;min-height:0;font-size:10px;line-height:1.2;color:#4e2324;border-bottom:1px solid rgba(125,66,70,.13)}.invoice-row>span{display:flex;align-items:center;justify-content:center;min-width:0;padding:2px;border-left:1px solid rgba(125,66,70,.13);overflow:hidden}.invoice-row>span:last-child{border-left:0}.invoice-row .item-name{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:2px 4px}.invoice-row .item-name strong,.invoice-row .item-name small{display:block;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.invoice-row .item-name strong{font-size:10px}.invoice-row .item-name small{font-size:9px;line-height:1.15;color:#75494b}.total{position:absolute;z-index:3;right:8%;width:14%;height:2.8%;display:flex;align-items:center;justify-content:center;font-weight:800;color:#68141b;font-size:10px}.subtotal{top:71.1%}.final{top:79.9%;font-size:11px}.shipping-mask{position:absolute;z-index:2;top:74.3%;right:7.5%;width:36%;height:4.2%;background:#faece8}.page-counter{position:absolute;z-index:2;bottom:1.3%;left:4%;font-size:8px;color:#8c5b5d}@media print{html,body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body>${pagesHtml}</body></html>`;

return [{json:{...event,invoiceHtml,invoiceFileName:`${invoiceFileBase}.pdf`,invoiceDeliveryChatId,isManualReview,telegramCaption,paidCallbackData:`invoicepay:paid:${invoiceId}`,waitingCallbackData:`invoicepay:waiting:${invoiceId}`,firstCardCopyText:String(firstPaymentAccount.CardNumber??''),firstCardCopyLabel:`📋 کپی کارت ${firstPaymentAccount.BankName??'اول'}`,secondCardCopyText:String(secondPaymentAccount.CardNumber??''),secondCardCopyLabel:`📋 کپی کارت ${secondPaymentAccount.BankName??'دوم'}`,artifactType:'InvoicePdf'}}];

const item = $input.first();
const html = String(item.json.invoiceHtml ?? '');
if (!html) throw new Error('Invoice HTML is empty.');
return [{json: item.json, binary: {data: {data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'index.html'}}}];

const event = $('Build Invoice HTML').first().json;
const telegram = $input.first().json;
const fileId = telegram.document?.file_id ?? telegram.result?.document?.file_id;
if (!fileId) throw new Error('Telegram did not return the PDF file_id.');
return [{json: {sourceEventId: event.eventId, orderId: event.orderId, type: 'InvoicePdf', fileUrl: null, externalFileId: fileId, contentType: 'application/pdf'}}];
